using System.Data;
using LittleSteps.Api.Data;
using LittleSteps.Api.Domain;
using LittleSteps.Api.Mapping;
using LittleSteps.Api.ViewModels;
using Microsoft.EntityFrameworkCore;
using E=LittleSteps.Api.Data.Entities;
namespace LittleSteps.Api.Services;
public interface IAttendanceService {Task<object> Get(E.Staff actor,DateOnly? date,int? classId);Task Save(E.Staff actor,AttendanceRequest request);}
public sealed class AttendanceService(AppDbContext db,IAuditService audit,SchoolClock clock):IAttendanceService
{
 private Teacher Teacher(E.Staff actor,int? classId){if(StaffFactory.FromEntity(actor) is not Teacher teacher || teacher.ClassId is null)throw new DomainException("You have no assigned class.",403);if(classId.HasValue&&!teacher.CanMarkAttendanceFor(classId.Value))throw new DomainException("You may access only your own class.",403);return teacher;}
 // Class history determines the roster on the chosen day, so transfers do not rewrite past attendance.
 private async Task<List<E.Student>> Roster(int classId,DateOnly date){var ids=await db.ClassTransfers.Where(t=>t.EffectiveDate<=date).GroupBy(t=>t.StudentId).Select(g=>g.OrderByDescending(t=>t.EffectiveDate).ThenByDescending(t=>t.TransferId).First()).ToListAsync();var members=ids.Where(t=>t.ToClassId==classId).Select(t=>t.StudentId).ToArray();return await db.Students.Include(s=>s.Class).Where(s=>s.IsActive&&members.Contains(s.StudentId)).OrderBy(s=>s.FirstName).ToListAsync();}
 public async Task<object> Get(E.Staff actor,DateOnly? date,int? classId){var teacher=Teacher(actor,classId);var day=date??clock.Today;if(day>clock.Today)throw new DomainException("Future attendance dates are not allowed.");var weekend=day.DayOfWeek is DayOfWeek.Saturday or DayOfWeek.Sunday;var roster=await Roster(teacher.ClassId!.Value,day);var records=await db.AttendanceRecords.Include(a=>a.MarkedByStaff).Where(a=>a.ClassId==teacher.ClassId&&a.AttendanceDate==day).ToListAsync();var(start,end)=clock.Day(day);var exits=await db.EarlyExits.Where(e=>e.Authorized&&e.OccurredAt>=start&&e.OccurredAt<end).ToListAsync();var saved=records.OrderByDescending(a=>a.CorrectedAt??a.MarkedAt).FirstOrDefault();return new{classId=teacher.ClassId,className=actor.Class!.Name,date=day,weekend,saved=records.Count>0,savedBy=saved?.MarkedByStaff.FullName,savedAt=saved?.CorrectedAt??saved?.MarkedAt,students=roster.Select(s=>new{student=StudentService.Summary(s),status=records.SingleOrDefault(a=>a.StudentId==s.StudentId)?.Status.ToString(),leftEarlyAt=exits.FirstOrDefault(e=>e.StudentId==s.StudentId)?.OccurredAt})};}
 public async Task Save(E.Staff actor,AttendanceRequest r){var teacher=Teacher(actor,r.ClassId);await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable);var roster=await Roster(teacher.ClassId!.Value,r.Date);var records=await db.AttendanceRecords.Where(a=>a.ClassId==teacher.ClassId&&a.AttendanceDate==r.Date).ToListAsync();var sheet=new AttendanceSheet(teacher.ClassId.Value,r.Date,clock.Today,roster.Select(s=>s.StudentId),records.Count>0);if(r.Correction)sheet.StartCorrection();if(r.Marks is null||r.Marks.Select(m=>m.StudentId).Distinct().Count()!=r.Marks.Length)throw new DomainException("Each student must have exactly one mark.");foreach(var m in r.Marks){var status=m.Status switch{"P"=>AttendanceStatus.Present,"A"=>AttendanceStatus.Absent,_=>throw new DomainException("Choose Present or Absent.")};sheet.Mark(m.StudentId,status);}sheet.Save(teacher,clock.Now);foreach(var m in sheet.Marks){var entry=records.SingleOrDefault(a=>a.StudentId==m.StudentId);if(entry is null){entry=new E.AttendanceRecord{StudentId=m.StudentId,ClassId=teacher.ClassId.Value,AttendanceDate=r.Date,MarkedAt=clock.Now};db.AttendanceRecords.Add(entry);}else entry.CorrectedAt=clock.Now;entry.MarkedByStaffId=actor.StaffId;entry.Status=m.Status==AttendanceStatus.Present?'P':'A';}audit.Record("Attendance",r.Correction?"Attendance corrected":"Attendance saved",actor.Class!.Name+" · "+r.Date.ToString("yyyy-MM-dd"),staff:actor);await db.SaveChangesAsync();await tx.CommitAsync();}
}
